/// Итератор по строкам большого файла, который не загружает весь файл в память.
///
/// Данный тип обёртывает [`BufReader`], читающий из [`File`], и предоставляет
/// итерацию по логическим строкам (разделённым символом `\n`). Каждая строка
/// читается побуквенно/побайтово из буфера чтения, поэтому потребление памяти
/// ограничено размером внутреннего буфера `BufReader` (по умолчанию 8 КБ)
/// плюс текущую строку, а не всего файла.
///
/// # Пример использования
///
/// ```no_run
/// use std::path::Path;
///
/// let path = Path::new("big_file.txt");
/// let mut line_iter = LineIterator::new(path).expect("не удалось открыть файл");
///
/// for (num, result) in line_iter.enumerate() {
///     match result {
///         Ok(line) => println!("Строка {}: {}", num + 1, line),
///         Err(e) => eprintln!("Ошибка чтения: {}", e),
///     }
/// }
/// ```
pub struct LineIterator {
    /// Буферизированный читатель, который хранит небольшой внутренний буфер
    /// (обычно 8 КБ) и читает данные из файла порциями.
    reader: BufReader<File>,
}

impl LineIterator {
    /// Создаёт новый итератор по строкам указанного файла.
    ///
    /// Файл открывается в режиме только для чтения. Если файл не существует
    /// или нет прав на чтение, метод вернёт ошибку.
    ///
    /// # Аргументы
    ///
    /// * `path` — путь к файлу, который будет читаться построчно.
    ///
    /// # Возвращаемое значение
    ///
    /// Успешный результат содержит экземпляр [`LineIterator`], ошибка —
    /// [`std::io::Error`] с описанием проблемы при открытии файла.
    pub fn new<P: AsRef<std::path::Path>>(path: P) -> io::Result<Self> {
        // Открываем файл. File::open возвращает Result<File, io::Error>.
        let file = File::open(path)?;

        // Оборачиваем File в BufReader. BufReader использует внутренний буфер
        // (по умолчанию 8 КБ), чтобы минимизировать системные вызовы read().
        // Это критически важно для производительности: без буферизации каждый
        // вызов read_line() мог бы вызывать системный вызов для каждого байта.
        let reader = BufReader::new(file);

        Ok(Self { reader })
    }

