public Optional<User> findActive(String login) {
    // Получаем поток из коллекции всех пользователей
    return users.stream()
        // Фильтруем пользователей, у которых логин совпадает с переданным (без учета регистра)
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Оставляем только тех пользователей, которые не заблокированы и чей срок действия еще не истек
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Возвращаем первого найденного пользователя, соответствующего условиям, или пустой Optional
        .findFirst();
}
