/// <summary>
/// Выполняет асинхронное действие с повторными попытками при возникновении ошибок HTTP.
/// Использует экспоненциальную задержку между попытками для снижения нагрузки на сервер.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число (например, статус-код или результат операции).</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат успешного выполнения действия.</returns>
/// <exception cref="InvalidOperationException">Бросается, если все попытки исчерпаны и ошибка не была обработана (теоретически недостижимый случай из-за логики цикла).</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл повторяется от 0 до (attempts - 1), то есть ровно 'attempts' раз
    for (var i = 0; i < attempts; i++)
    {
        try 
        {
            // Пытаемся выполнить переданное асинхронное действие
            // Если оно завершается успешно — сразу возвращаем результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только ошибки HTTP (например, таймауты, сетевые сбои)
