// Функция worker представляет собой функцию-работник, которая обрабатывает задачи из канала jobs.
// Она принимает:
//   - jobs: канал для получения задач (Job) от отправителя
//   - results: канал для отправки результатов обработки (Result) получателю
//   - wg: указатель на WaitGroup для корректного завершения работы воркера
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Деферированный вызов wg.Done() гарантирует, что счётчик WaitGroup будет уменьшен
    // при выходе из функции, независимо от причины выхода (нормальное завершение или паника).
    defer wg.Done()

    // Цикл range по каналу jobs блокирует выполнение до тех пор, пока не поступит новая задача.
    // Когда канал jobs будет закрыт, цикл автоматически завершится.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если во время обработки возникла ошибка:
        if err != nil {
            // Логируем ошибку с идентификатором задачи (j.ID) и текстом ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей, не отправляя результат.
            continue
        }

        // Если обработка прошла успешно, отправляем результат r в канал results.
        // Это блокирующая операция: если буфер канала заполнен, воркер будет ждать,
        // пока получатель не заберёт предыдущий результат.
        results <- r
    }
}
