/**
 * Создаёт функцию с дебаунсингом (задержкой выполнения).
 * 
 * @param fn - Функция, которую нужно обернуть в дебаунс.
 * @param ms - Задержка в миллисекундах перед выполнением функции.
 * @returns Обёрнутая функция, которая будет вызываться только после того,
 *          как перестанут приходить новые вызовы в течение указанного времени.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Изначально она не определена, так как таймер ещё не был создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (т.е., предыдущий вызов ещё не отработал),
    // очищаем его, чтобы отменить запланированное выполнение.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер на задержку `ms`.
    // По истечении этого времени будет вызвана исходная функция `fn`
    // с последними переданными аргументами `args`.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

