/**
 * Безопасно получает значение по ключу из карты.
 * Если значения нет, вызывает переданную фабричную функцию для его создания и сохраняет результат в карту.
 * Вся операция выполняется синхронно (с блокировкой на объекте карты), чтобы избежать гонок данных при многопоточном доступе.
 *
 * @param K Тип ключей карты.
 * @param V Тип значений карты.
 * @param key Ключ, по которому нужно получить или создать значение.
 * @param factory Лямбда-функция, которая будет вызвана только если значение с указанным ключом отсутствует.
 * @return Значение, связанное с ключом (либо существующее, либо созданное фабрикой).
 */
fun <K, V> MutableMap<K, V>.getOrPutSafe(key: K, factory: () -> V): V =
    // Блокируем доступ к карте на время выполнения операции, обеспечивая атомарность "проверка + запись"
    synchronized(this) {
        // Пытаемся получить значение по ключу.
        // Если оно существует — возвращаем его.
        // Если нет (null) — вызываем factory(), сохраняем результат обратно в карту под тем же ключом
        // и возвращаем это новое значение.
        this[key] ?: factory().also { this[key] = it }
    }
