/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в HashMap.
///
/// # Аргументы
/// * `s` - входная строка, где пары ключ-значение разделены точкой с запятой (`;`),
///   а внутри каждой пары ключ и значение разделены знаком равенства (`=`).
///
/// # Возвращаемое значение
/// `HashMap<String, String>`, где:
/// - ключи приведены к нижнему регистру и очищены от пробелов по краям,
/// - значения очищены от пробелов по краям, но сохраняют исходный регистр.
///
/// Строки без знака `=` или пустые части игнорируются.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Разбиваем исходную строку на подстроки по символу ';'
    s.split(';')
        // Для каждой подстроки пытаемся найти первый вхождение '='.
        // Если '=' не найден (например, пустая часть или некорректный формат),
        // split_once вернет None, и filter_map отфильтрует такой элемент.
        .filter_map(|p| p.split_once('='))
        // Теперь у нас есть кортежи (ключ, значение).
        // Приводим ключ к нижнему регистру и убираем пробелы по краям.
        // Значение тоже очищаем от пробелов по краям, но оставляем регистр как есть.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        // Собираем все пары в HashMap.
        // При дубликатах ключей последнее значение перезапишет предыдущее.
        .collect()
}
