import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

public class BackpressureExample {
    public static void main(String[] args) {
        // 1. Создаем "быстрый" источник данных (производитель)
        // Он генерирует 10 элементов в секунду
        Flux<Integer> fastSource = Flux.range(1, 100)
                .delayElements(Duration.ofMillis(100)); // 1 элемент каждые 100 мс

        // 2. Создаем "медленного" потребителя
        // Он обрабатывает каждый элемент с задержкой в 500 мс
        AtomicInteger processedCount = new AtomicInteger(0);

        fastSource
                // Ключевой момент: указываем стратегию обработки backpressure
                // onBackpressureBuffer() создает буфер, чтобы не терять данные,
                // но если буфер переполнится — можно задать лимит и действие.
                .onBackpressureBuffer(10) // Буфер на 10 элементов

                // Имитация медленной обработки
                .doOnNext(item -> {
                    try {
                        Thread.sleep(500); // Потребитель тратит 500 мс на обработку
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    processedCount.incrementAndGet();
                    System.out.println("Обработан элемент: " + item + 
                                       " (всего обработано: " + processedCount.get() + ")");
                })

Конкурентность в Go (Голанге) — это одна из её ключевых особенностей, которая позволяет писать многопоточный код просто и безопасно. В отличие от Java или C++, где вы часто работаете с явными потоками (threads) и мьютексами (locks), в Go используется модель **CSP** (Communicating Sequential Processes).

### Ключевая идея: «Не общайтесь через общую память, а общайтесь через передачу памяти»

Вместо того чтобы заставлять несколько потоков одновременно читать/писать в одну переменную (что требует блокировок), вы создаёте независимые единицы выполнения — **горутины** (goroutines), которые обмениваются данными через **каналы** (channels).

#### Что такое горутина?
Это лёгкий поток, который запускается функцией `go`. Она очень дёшева по ресурсам (стартует за микросекунды и занимает мало памяти), поэтому можно запустить тысячи или даже миллионы горуutin одновременно.

#### Что такое канал?
Канал — это типизированный конвейер, по которому данные передаются между горутинами. Он обеспечивает:
1. **Синхронизацию**: Отправитель ждёт, пока получатель будет готов принять данные (если канал не буферизован).
2. **Безопасность**: Данные передаются целиком, нет гонок данных (data races).

---

### Пример кода: Простой обмен сообщениями

Представим, что у нас есть две задачи:
1. Одна горутина генерирует числа.
2. Другая горутина принимает эти числа и печатает их.

Они общаются через канал.

```go
package main

import (
    "fmt"
    "time"
)

func main() {
    // 1. Создаём канал для передачи целых чисел.
    // Канал без буфера: отправитель будет ждать, пока получатель не примет значение.
    ch := make(chan int)

    // 2. Запускаем первую горуутину (отправитель).
    // Функция sendNumbers будет выполняться параллельно с main.
    go func() {
        for i := 0; i < 5; i++ {
            fmt.Println("Отправляю:", i)
            ch <- i // Блокирующая операция: ждём, пока кто-то возьмёт число из канала
            time.Sleep(100 * time.Millisecond) // Имитация работы
        }
        close(ch) // Важно: закрываем канал, когда больше нечего отправлять
    }()

    // 3. Вторая часть (получатель) выполняется в основной горуутине (main).
    // Мы читаем из канала в цикле.
    for num := range ch {
        // range автоматически остановится, когда канал будет закрыт
        fmt.Println("Получил:", num)
    }

    fmt.Println("Все данные получены, программа завершена.")
}
```

